/**
 * Debounced autocomplete API client with request cancellation.
 */

let abortController: AbortController | null = null;

export interface AutocompleteResult {
  id: string;
  label: string;
  category?: string;
}

export interface AutocompleteResponse {
  results: AutocompleteResult[];
  query: string;
}

/**
 * Fetch autocomplete suggestions for a given query.
 * Cancels previous in-flight requests.
 */
export async function fetchAutocomplete(
  query: string
): Promise<AutocompleteResponse> {
  // Cancel previous request if in-flight
  if (abortController) {
    abortController.abort();
  }

  abortController = new AbortController();

  const params = new URLSearchParams({ q: query });
  const response = await fetch(`/api/autocomplete?${params}`, {
    signal: abortController.signal,
  });

  if (!response.ok) {
    throw new Error(`Autocomplete API error: ${response.status}`);
  }

  return response.json();
}
```

### `src/hooks/useSearchAutocomplete.ts`
```typescript
/**
 * Custom hook for managing debounced autocomplete search.
 */

import { useEffect, useState, useRef, useCallback } from 'react';
import {
  fetchAutocomplete,
  AutocompleteResult,
} from '../api/search';

interface UseSearchAutocompleteOptions {
  debounceMs?: number;
}

export function useSearchAutocomplete(
  query: string,
  { debounceMs = 400 }: UseSearchAutocompleteOptions = {}
) {
  const [suggestions, setSuggestions] = useState<AutocompleteResult[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const debounceTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const requestSequence = useRef(0);

  const fetchSuggestions = useCallback(
    async (q: string, sequence: number) => {
      if (!q.trim()) {
        setSuggestions([]);
        return;
      }

      setLoading(true);
      setError(null);

      try {
        const result = await fetchAutocomplete(q);

        // Discard stale responses
        if (sequence >= requestSequence.current) {
          setSuggestions(result.results);
        }
      } catch (err) {
        if (err instanceof Error && err.name !== 'AbortError') {
          setError(err.message);
        }
      } finally {
        setLoading(false);
      }
    },
    []
  );

  useEffect(() => {
    requestSequence.current += 1;
    const currentSequence = requestSequence.current;

    // Clear previous debounce timer
    if (debounceTimer.current) {
      clearTimeout(debounceTimer.current);
    }

    // Set new debounce timer
    debounceTimer.current = setTimeout(() => {
      fetchSuggestions(query, currentSequence);
    }, debounceMs);

    return () => {
      if (debounceTimer.current) {
        clearTimeout(debounceTimer.current);
      }
    };
  }, [query, debounceMs, fetchSuggestions]);

  return { suggestions, loading, error };
}
```

