/**
 * Dropdown component for autocomplete suggestions.
 */

import React, { useState, useRef, useEffect } from 'react';
import { AutocompleteResult } from '../api/search';
import './SearchAutocomplete.css';

interface SearchAutocompleteProps {
  suggestions: AutocompleteResult[];
  loading: boolean;
  onSelect: (result: AutocompleteResult) => void;
  isOpen: boolean;
}

export function SearchAutocomplete({
  suggestions,
  loading,
  onSelect,
  isOpen,
}: SearchAutocompleteProps) {
  const [selectedIndex, setSelectedIndex] = useState(-1);
  const listRef = useRef<HTMLUListElement>(null);

  // Reset selection when suggestions change
  useEffect(() => {
    setSelectedIndex(-1);
  }, [suggestions]);

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (!isOpen) return;

    switch (e.key) {
      case 'ArrowDown':
        e.preventDefault();
        setSelectedIndex((prev) =>
          prev < suggestions.length - 1 ? prev + 1 : prev
        );
        break;
      case 'ArrowUp':
        e.preventDefault();
        setSelectedIndex((prev) => (prev > 0 ? prev - 1 : -1));
        break;
      case 'Enter':
        e.preventDefault();
        if (selectedIndex >= 0 && suggestions[selectedIndex]) {
          onSelect(suggestions[selectedIndex]);
        }
        break;
      case 'Escape':
        e.preventDefault();
        setSelectedIndex(-1);
        break;
      default:
        break;
    }
  };

  if (!isOpen) return null;

  return (
    <div className="search-autocomplete">
      {loading && <div className="autocomplete-loading">Loading...</div>}
      {!loading && suggestions.length === 0 && (
        <div className="autocomplete-empty">No suggestions</div>
      )}
      {!loading && suggestions.length > 0 && (
        <ul
          ref={listRef}
          className="autocomplete-list"
          role="listbox"
          onKeyDown={handleKeyDown}
        >
          {suggestions.map((result, idx) => (
            <li
              key={result.id}
              className={`autocomplete-item ${
                idx === selectedIndex ? 'selected' : ''
              }`}
              role="option"
              aria-selected={idx === selectedIndex}
              onClick={() => onSelect(result)}
              onMouseEnter={() => setSelectedIndex(idx)}
            >
              <span className="item-label">{result.label}</span>
              {result.category && (
                <span className="item-category">{result.category}</span>
              )}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}
```

### `src/components/SearchBar.tsx` (Integration)
```typescript
/**
 * SearchBar with integrated autocomplete dropdown.
 */

import React, { useState } from 'react';
import { SearchAutocomplete } from './SearchAutocomplete';
import { useSearchAutocomplete } from '../hooks/useSearchAutocomplete';
import { AutocompleteResult } from '../api/search';
import './SearchBar.css';

interface SearchBarProps {
  onSearch: (query: string) => void;
}

export function SearchBar({ onSearch }: SearchBarProps) {
  const [query, setQuery] = useState('');
  const [isOpen, setIsOpen] = useState(false);

  const { suggestions, loading, error } = useSearchAutocomplete(query);

  const handleSelect = (result: AutocompleteResult) => {
    setQuery(result.label);
    setIsOpen(false);
    onSearch(result.label);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setIsOpen(false);
    onSearch(query);
  };

  return (
    <form className="search-bar" onSubmit={handleSubmit}>
      <input
        type="text"
        className="search-input"
        placeholder="Search products..."
        value={query}
        onChange={(e) => {
          setQuery(e.target.value);
          setIsOpen(true);
        }}
        onFocus={() => query && setIsOpen(true)}
        onBlur={() => setTimeout(() => setIsOpen(false), 200)}
        autoComplete="off"
      />
      {error && <div className="search-error">{error}</div>}
      <SearchAutocomplete
        suggestions={suggestions}
        loading={loading}
        onSelect={handleSelect}
        isOpen={isOpen && (suggestions.length > 0 || loading)}
      />
      <button type="submit" className="search-button">
        Search
      </button>
    </form>
  );
}
```

